text:
:is(#MsgHeadersToolbar, #FormatToolbox) {
  background-color: var(--layout-background-2);
  color: var(--layout-color-1);
  color-scheme: light-dark;
}

#MsgHeadersToolbar {
  grid-area: headers;
  display: grid;
  grid-template-rows: min-content minmax(0, min-content) min-content;
  grid-template-columns: auto fit-content(11.5rem) minmax(0, 1fr);
}

#top-gradient-box,
#recipientsContainer,
.address-row,
#subject-box {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
}

#FormatToolbox {
  grid-area: format-toolbar;
}
